import {TOWER_FLOORS,towerFrontier,towerTrainer,towerRewards,canEnterTower} from './tower-data.mjs';
import {trainerSrc} from './player-profile.mjs';
import {icon} from './art.mjs';
export function towerPage(g){
 const frontier=towerFrontier(g.state),done=frontier>TOWER_FLOORS;
 const selected=canEnterTower(g.state,g.towerSelected)?g.towerSelected:Math.min(frontier,TOWER_FLOORS);g.towerSelected=selected;
 const trainer=towerTrainer(selected,g.dex),cleared=selected<frontier,reward=towerRewards(selected),count=Math.min(TOWER_FLOORS,frontier-1);
 return g.heading('L’ASCENSION DES DRESSEURS','La Tour Infernale','Cinquante étages. Une équipe de six. Un dernier duel au-dessus des nuages.')+`
 <section class="tower-campaign" aria-label="Progression dans la Tour Infernale">
  <div class="tower-overview"><div><span>${done?'SOMMET CONQUIS':'PROCHAINE PORTE · ÉTAGE '+String(frontier).padStart(2,'0')}</span><strong>${count}<small> / ${TOWER_FLOORS} étages vaincus</small></strong></div><div class="tower-progress-track" role="progressbar" aria-label="Étages vaincus" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="50"><i style="width:${count/TOWER_FLOORS*100}%"></i></div><button data-act="tower-current">${done?'Revoir le sommet':'Revenir à mon étage'} ↑</button></div>
  <div class="tower-layout"><div class="tower-map-shell"><header><span>LE CHEMIN DU SOMMET</span><small>Fais défiler pour explorer la tour</small></header><div class="tower-map" tabindex="0" aria-label="Tour verticale : anciens étages en bas, sommet en haut"><div class="tower-spire"><div class="tower-crown"><span>✦</span><strong>LE SOMMET</strong><small>ÉTAGE ${TOWER_FLOORS} · COMBAT FINAL</small></div>${Array.from({length:TOWER_FLOORS},(_,i)=>TOWER_FLOORS-i).map(n=>{
   const unlocked=canEnterTower(g.state,n),old=n<frontier,current=n===frontier,active=n===selected;
   // Sealed floors deliberately contain no trainer identity, team or reward data.
   return `<div class="tower-floor ${unlocked?'unlocked':'sealed'} ${current?'frontier':''} ${active?'chosen':''} ${old?'cleared':''}" data-tower-floor="${n}"><div class="tower-floor-number"><small>ÉTAGE</small><b>${String(n).padStart(2,'0')}</b></div><button data-act="tower-select" data-floor="${n}" ${!unlocked?'disabled':''} aria-pressed="${active}" aria-label="${!unlocked?'Étage '+n+' scellé':old?'Rejouer l’étage '+n:'Étage '+n+' : prochain combat'}"><span class="tower-door"><i></i><b>${!unlocked?'◇':old?'✓':'⚔'}</b></span><span class="tower-floor-state">${!unlocked?'Scellé':old?'Vaincu · Rejouer':'Ton prochain défi'}</span></button>${current?`<img class="tower-map-trainer" src="${trainerSrc(towerTrainer(n,g.dex).avatar)}" alt="Dresseur du prochain étage">`:''}</div>`;
  }).join('')}<div class="tower-foundation"><strong>LES PORTES DE LA TOUR</strong><span>Chaque victoire ouvre la voie.</span></div></div></div><footer><span>✓ Vaincu</span><span>⚔ Prochain combat</span><span>◇ Scellé</span></footer></div>
  <aside class="tower-brief" aria-label="Combat sélectionné"><div class="tower-opponent"><span class="tower-selection-tag">${cleared?'ÉTAGE DÉJÀ VAINCU':trainer.final?'LE DERNIER DUEL':'TON PROCHAIN ADVERSAIRE'}</span><div class="tower-trainer-art"><div></div><img src="${trainerSrc(trainer.avatar)}" alt="${g.escape(trainer.name)}"></div><span class="eyebrow">ÉTAGE ${String(selected).padStart(2,'0')} · ${trainer.title.toUpperCase()}</span><h2>${g.escape(trainer.name)}</h2><p>veut se battre !</p><div class="tower-opponent-meta"><span>${trainer.keys.length} Pokémon</span><span>Niveau ${trainer.level}</span>${trainer.final?'<span>Combat final</span>':''}</div></div>
   <div class="tower-reward-panel"><div><h3>${cleared?'Récompenses déjà obtenues':'Récompenses de première victoire'}</h3><span>${cleared?'✓ Récupérées':'À remporter'}</span></div><div class="tower-loot ${cleared?'claimed':''}"><span><i>▱</i><b>${reward.tickets}</b><small>Tickets universels</small></span><span><i>◈</i><b>${reward.candies}</b><small>Bonbons</small></span><span><i>✦</i><b>${reward.coins}</b><small>Poussières d’étoiles</small></span></div><p>${cleared?'Rejoue ce combat pour affiner ta stratégie. Aucun ticket, objet, bonbon ni XP supplémentaire.':'+ '+reward.xp+' XP pour chaque Pokémon de ton équipe. Les récompenses ne peuvent être obtenues qu’une fois.'}</p></div>
   <div class="tower-your-team"><div><h3>Ton équipe</h3><button data-act="route" data-page="team">Préparer →</button></div><div>${g.state.team.map(k=>`<img src="${icon(k)}" alt="${g.escape(g.poke(k).name)}">`).join('')}${Array.from({length:6-g.state.team.length},()=>'<span>＋</span>').join('')}</div></div>
   <button class="primary tower-enter" data-act="tower-fight" data-floor="${selected}">${cleared?'Réaffronter ce dresseur':trainer.final?'Défier le gardien du sommet':'Affronter '+g.escape(trainer.name)} <span>→</span></button><small class="tower-secrecy">Les adversaires et récompenses des étages suivants restent cachés.</small>
  </aside></div>
 </section>`;
}
export function focusTower(g){if(g.page!=='tower')return;requestAnimationFrame(()=>{const map=g.root.querySelector('.tower-map'),row=g.root.querySelector(`[data-tower-floor="${g.towerSelected}"]`);if(map&&row)map.scrollTop=row.offsetTop-map.clientHeight*.55+row.clientHeight/2})}
